package com.aistock.user.statistics;
import com.aistock.user.support.AuthDatabaseFixture;import com.aistock.common.statistics.*;import com.fasterxml.jackson.databind.ObjectMapper;import java.time.*;import org.junit.jupiter.api.*;import org.springframework.util.LinkedMultiValueMap;import static org.junit.jupiter.api.Assertions.*;
@Tag("mysql") class UserStatisticsMysqlTest {
 static StatisticsWindow window(){var q=new LinkedMultiValueMap<String,String>();q.add("from","2026-10-20");q.add("to","2026-10-22");return StatisticsWindow.parse(q,Clock.fixed(Instant.parse("2026-10-22T04:00:00Z"),ZoneOffset.UTC));}
 @Test void historicalLoginsAreDistinctAcrossDaysAndReadsDoNotWrite()throws Exception{
  var db=new AuthDatabaseFixture();var a=UserStatisticsData.account(db,"a@example.com","USER","ENABLED",Instant.parse("2026-10-19T16:00:00Z"));var b=UserStatisticsData.account(db,"b@example.com","USER","DISABLED",Instant.parse("2020-01-01T00:00:00Z"));UserStatisticsData.account(db,"c@example.com","ADMIN","ENABLED",Instant.parse("2026-10-20T15:59:59Z"));
  UserStatisticsData.session(db,a,"2026-10-20T01:00:00Z",true);UserStatisticsData.session(db,a,"2026-10-20T02:00:00Z",false);UserStatisticsData.session(db,a,"2026-10-20T16:00:00Z",false);UserStatisticsData.session(db,b,"2026-10-20T03:00:00Z",false);UserStatisticsData.session(db,b,"2026-10-22T16:00:00Z",false);
  var before=db.jdbc().queryForList("select user_id,last_active_at,revision from user_account order by user_id");var sessions=db.jdbc().queryForList("select * from login_session order by session_id");var repo=new UserStatisticsRepository(db.jdbc());var result=repo.summary(window(),Instant.parse("2026-10-22T04:00:00Z"));
  assertEquals("3",result.totalUsers());assertEquals("2",result.enabledUsers());assertEquals("1",result.disabledUsers());assertEquals("2",result.registrations());assertEquals("4",result.successfulLogins());assertEquals("2",result.distinctLoginUsers());assertEquals("3",result.loginDaily().get(0).successfulLogins());assertEquals("2",result.loginDaily().get(0).distinctUsers());assertEquals("1",result.loginDaily().get(1).distinctUsers());assertEquals("0",result.loginDaily().get(2).distinctUsers());assertEquals("2",result.registrationDaily().get(0).count());assertEquals("0",result.registrationDaily().get(1).count());
  assertEquals("2",result.roleCounts().stream().filter(x->x.key().equals("USER")).findFirst().orElseThrow().count());
  assertEquals(before,db.jdbc().queryForList("select user_id,last_active_at,revision from user_account order by user_id"));assertEquals(sessions,db.jdbc().queryForList("select * from login_session order by session_id"));
  var json=new ObjectMapper().findAndRegisterModules().writeValueAsString(result);for(var secret:new String[]{"example.com","password","token_hash","session_id","email"})assertFalse(json.contains(secret));assertEquals(result,repo.summary(window(),Instant.parse("2026-10-22T04:00:00Z")));
 }
 @Test void emptyDatasetHasZeroFilledDaysAndRoleCounts(){var db=new AuthDatabaseFixture();var result=new UserStatisticsRepository(db.jdbc()).summary(window(),Instant.now());assertEquals("0",result.totalUsers());assertEquals("0",result.distinctLoginUsers());assertEquals(3,result.loginDaily().size());assertEquals(2,result.roleCounts().size());assertTrue(result.roleCounts().stream().allMatch(x->x.count().equals("0")));}
}
